scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap035hemei == 0) @Talk0;
	If ($Talkmap035hemei == 1) @Talk1;
	Return;
@Talk0:	
	Say("何梅：独孤公子和那位张姑娘认识很久了吗？", 66);
	Say("独孤剑：我与她相识不久，只见过两次面而已。", 1);
	Say("何梅：只见过两次面，你就肯为她只身犯险，独孤公子真是重情重义之人。", 66);
	Say("独孤剑：何姑娘过奖了。", 1);
	Assign($Talkmap035hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子真是一个重情重义之人哪。", 66);
	Return;

scripts.妇人对话.txt:
// 与临安城东的年轻妇人的对话

	Say("安芸：哎呀，我好久没有见到象公子这样英姿不凡的小伙子了，公子要不要坐下来喝杯茶呀？", 0);
	Say("独孤剑：多谢姑娘好意，我还有事，下次吧。", 1);
	Return;

scripts.酒客对话.txt:
// 与临安城东的酒客对话

	Say("酒客华举：马兄，最近你老是闷闷不乐，是有什么心事吗？", 0);
	Say("酒客马中宝：华兄，你我身为七尺男儿，却不能驰骋疆场，杀敌报国，叫人如何不愁烦郁闷？", 0);
	Say("酒客华举：是啊，朝廷主和不主战，你我空有一身好武艺，却报国无门呐！", 0);
	Return;

scripts.云笑风对话.txt:
//和云笑风对话

	If ($Suba == 201) @Sub201;
	If ($Suba == 210) @Sub210;
	If ($Suba == 220) @Sub220;
	
	Say("北国人：……吴兄怎么还不回来？唉——", 0);
	Say("独孤剑：兄台为何做此长叹。", 1);
	Say("北国人：这……", 0);
	Say("酒肆老板：这位客官来的正好，来给我们评评理。这人喝了酒不给钱，还振振有词，你说，在咱的大宋国里，有这么便宜的事吗？", 0);
	Say("北国人：云某不是不给，只是盘缠都在刚才那位朋友身上，某家现下实在身无分文。", 0);
	Say("酒肆老板：这些金狗奸诈凶狠，谁信得你们……");
	Say("北国人：你！……朋友，大家都是汉人，何苦口出恶言。", 0);
	Say("酒肆老板：哼！金狗，就是金狗！", 0);
	Say("独孤剑：掌柜，这位朋友欠你多少酒钱？", 1);
	Say("酒肆老板：你……纹，纹银二两整。", 0);
	Say("独孤剑：好，这是纹银二两，你点清楚！", 1);
	
	GetMoneyNum();
	If ($MoneyNum << 2) @NotEnough;
	If ($MoneyNum >= 2) @Enough;
	
 @NotEnough:
	Say("酒肆老板：不用点清楚了，这里哪有二两。呸！想耍阔，也不掂点份量。", 0);
	Say("独孤剑：这个——", 4);
	Assign($Suba, 201);
	Return;

 @Enough:	
	Say("酒肆老板：正好，正好——", 0);
	NpcGoto("茶馆老板", 15, 17);
	SetNpcDir("茶馆老板", 4);
	SetNpcDir("茶馆老板",3);
	Say("北国人：多谢兄台，滴水之恩，定当涌泉相报。");
	Say("独孤剑：出门在外都是朋友，云兄不必客气。", 2);
	Say("北国人：好！好！如果这位兄台不嫌弃，云某愿和你交个朋友。在下云笑风。");
	Say("独孤剑：在下独孤剑。云兄看来是北方人士，不知如何到此？", 1);
	Say("云笑风：不瞒独孤兄，在下乃是幽州人士，祖居中都，家中略有资财。");
	Say("云笑风：云某平生有一挚友，名叫草草，两人惺惺相惜，引为知己。一年前，这位朋友南下江南，起初尚有鸿书往来，半年前突然音信皆无。云某数次托人打听，始终未果。某料必有事故发生，因此散了家资，只身南下来寻访他的踪迹。");
	Say("独孤剑：想不到云兄重情至此。", 1);
	Say("云笑风：千金易得，知己难求。换作是草草，只怕早就前来寻找云某了……某心急如焚，却始终不得半点消息。在临安城盘桓月余，昨日突然得到草草的消息。");
	Say("独孤剑：哦，云兄是如何得到的？", 1);
	Say("云笑风：一个叫吴来的朋友告诉云某，他有草草的消息，不过需要银子作盘缠打点，约我今日在此相见。今日云某如约前来，把身上剩下的两百两盘缠交给了吴朋友，让他进城准备车马、打点人手。可是已过了两个时辰，这位朋友仍未返还。");
	Say("独孤剑：吴来？", 1);
	Say("云笑风：这位掌柜硬说吴朋友在此欠下了二两酒钱，要我付帐。云某已身无分文，故在此争执，幸得独孤兄解围。");
	Say("独孤剑：原来如此。这样吧，云兄且现在此处等候，小弟进城打听打听。", 1);
	Say("云笑风：如此甚好。那多谢独孤兄。");
	Assign($Suba,210);
	Return;
	
@Sub201:
	Say("北国人：兄台的好意某家心领了。兄台不必勉强！");
	
	GetMoneyNum();
	If ($MoneyNum << 2) @NotEnough1;
	If ($MoneyNum >= 2) @Enough1;
	
 @NotEnough1:
	Say("独孤剑：算了，银子还是不够！", 9);
	Return;
 
 @Enough1:
 	Say("独孤剑：好，这是纹银二两，你点清楚！", 1);
	Say("酒肆老板：正好，正好——", 0);
	SetNpcDir("茶馆老板",3);
	Say("北国人：多谢兄台，滴水之恩，定当涌泉相报。");
	Say("独孤剑：出门在外都是朋友，云兄不必客气。", 2);
