	Say("云笑风：不瞒独孤兄，在下乃是幽州人士，祖居中都，家中略有资财。");
	Say("云笑风：云某平生有一挚友，名叫草草，两人惺惺相惜，引为知己。一年前，这位朋友南下江南，起初尚有鸿书往来，半年前突然音信皆无。云某数次托人打听，始终未果。某料必有事故发生，因此散了家资，支身南下来寻访他的踪迹。");
	Say("独孤剑：想不到云兄重情至此。", 1);
	Say("云笑风：千金易得，知己难求。换作是草草，只怕早就前来寻找云某了……某心急如焚，却始终不得半点消息。在临安城盘桓月余，昨日突然得到草草的消息。");
	Say("独孤剑：哦，云兄是如何得到的？", 1);
	Say("云笑风：一个叫吴来的朋友告诉云某，他有草草的消息，不过需要银子作盘缠打点，约我今日在此相见。今日云某如约前来，把身上剩下的两百两盘缠交给了吴朋友，让他进城准备车马、打点人手。可是已过了两个时辰，这位朋友仍未返还。");
	Say("独孤剑：吴来？", 1);
	Say("云笑风：这位掌柜硬说吴朋友在此欠下了二两酒钱，要我付帐。云某已身无分文，故在此争执，幸得独孤兄解围。");
	Say("独孤剑：原来如此。这样吧，云兄且现在此处等候，小弟进城打听打听。", 1);
	Say("云笑风：如此甚好。那多谢独孤兄。");
	Assign($Suba,210);
	Return;
	
@Sub210:
	Say("云笑风：就拜托独孤兄了。");
	Return;
	
@Sub220:
	Say("云笑风：独孤兄，可有什么消息？",0);
	Say("独孤剑：这……", 1);
	FadeOut();
	Say("独孤剑将吴来的消息告知云笑风。");
	
	Sleep(800);
	FadeIn();
	Say("云笑风：苍天哪！你待云某何其薄也——",0);
	Say("独孤剑：……", 1);
	Say("独孤剑：那，云兄今后有何打算？", 1);
	Say("云笑风：……",0);
	Say("云笑风：先回北方再说罢。此地云某也无心久留，留在江南只会徒增伤感……",0);
	Say("独孤剑：云兄也不必如此绝望。吴来的话未可全信……不如小弟在江南给云兄四处打听，或有所获。",1);
	Say("云笑风：那就多谢独孤兄弟了。",0);
	Say("独孤剑：云兄这便回幽州？", 1);
	Say("云笑风：为兄还想先去一趟湖南……独孤兄弟，就此别过！",0);
	Say("独孤剑：后会有期！",1);
	Say("云笑风：对了，这只护腕兄弟收下。这本是一对，我与草草各留下一只，他日倘若兄弟真能找到草草，可以此为凭。",0);
	Say("独孤剑：兄弟记着了！",1);
	Say("云笑风：拜托了！",0);
	Say("独孤剑：云兄珍重！", 1);
	
	NpcGotoEx("云笑风", 9,30);
	Sleep(300);
	SetPlayerDir(1);
	NpcGoto("云笑风", 9,30);
	DelNpc("云笑风");
	AddGoods("Goods412_一只护腕.ini");
	
	GetMoneyNum();
	If ($MoneyNum << 100) @NotEnough2;
	If ($MoneyNum >= 100) @Enough2;
	
@NotEnough2:
	Assign($NoEnd,1);
	Return;
	
@Enough2:
	Say("归还了一百两银子。");
	AddMoney(-100);
	Return;

scripts.卖鱼人对话.txt:
// 与临安城东卖鱼人的对话

	If ($Event == 80) @Event80;
	
	Say("卖鱼人：又肥又大的鲫鱼，活蹦乱跳的鲢鱼，买一条回去煲汤喝吧。", 0);
	Return;
	
@Event80:
	If ($Talkmap035maiyuren == 0) @Talk0;
	If ($Talkmap035maiyuren == 1) @Talk1;
@Talk0:	
	Say("卖鱼人：连青天白日也有强抢民女的……唉，生逢乱世！", 0);
	Say("独孤剑：老伯，那些人往那里去了？", 1);
	Say("卖鱼人：那几个黑衣人像是往渔村方向去了。", 0);
	Say("独孤剑：多谢！", 1);
	Assign($Talkmap035maiyuren, 1);
	Return;
@Talk1:
	Say("卖鱼人：小伙子，看你相貌堂堂，想要长寿的话，还是不要去惹那伙贼人了。", 0);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap035jia == 0) @Talk0;
	If($Talkmap035jia == 1) @Talk1;
	If($Talkmap035jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：河边茶铺的老板娘最喜欢年轻漂亮的小伙子啦，每次我找她，她都爱理不理的。", 207);
	Assign($Talkmap035jia, 1);
	Return;	
@Talk1:
	Say("贾老实：今天的鱼好像挺新鲜的，待会买几斤回去煲汤喝。", 207);
	Assign($Talkmap035jia, 2);
	Return;
@Talk2:
	Say("贾老实：老弟，你好像不太爱说话喔。", 207);
	Return;

